import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.io.PrintWriter;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String line = br.readLine();if (line == null) return;int n = Integer.parseInt(line.trim());int groups = 0;String last = "";for (int i = 0; i < n; i++) {String current = br.readLine();if (!current.equals(last)) {groups++;}last = current;}out.println(groups);out.flush();out.close();}}